Object.assign(DMI18N.S,{
 nursery:['Nursery','Viveiro'],eggs:['Eggs','Ovos'],rest:['Rest','Descanso'],hp:['HP','HP'],tp:['TP','TP'],technique:['Technique','Técnica'],effort:['Effort','Esforço'],attack:['Attack','Ataque'],defense:['Defense','Defesa'],wisdom:['Wisdom','Sabedoria'],speed:['Speed','Velocidade'],fatigue:['Fatigue','Fadiga'],settings:['Settings','Opções'],hunger:['Hunger','Alimentação'],medicine:['Medicine','Remédio'],clean:['Clean','Limpar'],meat:['Meat','Carne'],status:['Status','Status'],album:['DIGIDEX','DIGIDEX'],colosseum:['Colosseum','Colosseu'],netplay:['Netplay','Online'],help:['Help','Ajuda'],menu:['Menu','Menu'],back:['Back','Voltar'],saveExit:['Save & exit','Salvar e sair'],newGame:['New game','Novo jogo'],continue:['Continue','Continuar'],loadSave:['Load save','Carregar save'],about:['About','Sobre'],yes:['Yes','Sim'],no:['No','Não'],delete:['Delete','Deletar'],confirm:['Confirm','Confirmar'],owned:['Owned','Adquiridos'],all:['All','Todos'],next:['Next','Próximo'],battle:['Battle','Batalhar'],victory:['Victory!','Vitória!'],defeat:['Defeat','Derrota'],age:['Total age','Idade total'],stageAge:['Stage age','Idade da fase'],careMistakes:['Care mistakes','Erros de cuidado'],wins:['Wins','Vitórias'],training:['Training','Treinando'],healthy:['Healthy','Saudável'],sick:['Sick','Doente'],injured:['Injured','Ferido'],resting:['Resting','Descansando'],tired:['Too tired — drag to Rest','Exausto — arraste para Descanso'],hungry:['Hungry — drop some meat','Com fome — coloque carne'],emptySlot:['Empty slot · choose an egg','Slot vazio · escolha um ovo'],fullSlots:['Both slots are occupied. Delete a pet to free a slot.','Os dois slots estão ocupados. Delete um pet para liberar um slot.'],choosePet:['Choose your fighter','Escolha seu lutador'],needRookie:['Battles unlock at Rookie. Rest and treat injuries before fighting.','Batalhas liberadas em Rookie. Descanse e trate ferimentos antes de lutar.'],confirmNew:['Start over? This replaces this fork’s current save and achievements.','Começar do zero? Isso substitui o save e as conquistas deste fork.'],confirmNew2:['Confirm NEW GAME? Your current progress will be lost.','Confirmar NOVO JOGO? Seu progresso atual será perdido.'],delete1:['Delete this pet? Its slot will become available. DIGIDEX records and achievements remain.','Deletar este pet? O slot será liberado. Registros da DIGIDEX e conquistas permanecem.'],delete2:['Permanently delete this pet? This cannot be undone.','Deletar este pet definitivamente? Isso não pode ser desfeito.'],saved:['Progress saved locally','Progresso salvo localmente'],saveFailed:['Browser autosave failed. Export a backup using Save & exit.','Autosave falhou. Exporte um backup usando Salvar e sair.'],invalidSave:['Invalid or incompatible save','Save inválido ou incompatível'],hatched:['{name} hatched!','{name} nasceu!'],evolved:['Evolved into {name}!','Evoluiu para {name}!'],healed:['Medicine applied','Remédio aplicado'],deleted:['Pet deleted','Pet deletado'],locked:['Locked','Bloqueado'],unlocked:['Unlocked','Desbloqueado'],initial:['Available from the start','Disponível desde o início'],poolWins:['Win {n} battles','Vença {n} batalhas'],poolAlbum:['Obtain {n} species','Obtenha {n} espécies'],poolRound:['Reach round {n}','Alcance a rodada {n}'],poolOnline:['Win {n} online battles or reach round 90','Vença {n} batalhas online ou alcance a rodada 90'],poolClear:['Clear all {n} rounds','Complete as {n} rodadas'],evoWait:['Minimum stage time','Tempo mínimo da fase'],evoReady:['Age reached · training determines evolution','Idade atingida · o treino determina a evolução'],finalStage:['Final stage for this route','Fase final desta linha'],dragHint:['Drag pets to cages · drag empty ground to pan','Arraste pets às áreas · arraste o chão para navegar'],collection:['Raise · train · discover','Crie · treine · descubra'],subtitle:['Two companions. One afternoon of possibilities.','Dois companheiros. Uma tarde de possibilidades.'],localSave:['Local save · autosave every 30s','Save local · autosave a cada 30s'],name:['Name','Nome'],stage:['Stage','Fase'],health:['Health','Saúde'],specialization:['Training budget','Pontos de treino'],specializationHelp:['When the budget is full, training shifts points from other stats. You can always change your specialization.','Com o limite cheio, o treino transfere pontos de outros atributos. Você sempre pode mudar a especialização.'],best:['Best','Melhor'],round:['Round','Rodada'],clears:['Clears','Conclusões'],unused:['Not obtainable: Jogress is outside this version.','Não obtível: Jogress está fora desta versão.'],hostRole:['HOST','HOST'],challengerRole:['CHALLENGER','DESAFIANTE'],youRole:['YOU','VOCÊ'],opponentRole:['OPPONENT','OPONENTE'],rematch:['Rematch','Revanche'],waiting:['Waiting for confirmation…','Aguardando confirmação…'],rematchChallenge:['You have been challenged to a rematch.','Você foi desafiado para uma revanche.'],connect:['Connect','Conectar'],disconnect:['Disconnect','Desconectar'],nickname:['Nickname','Apelido'],roomName:['Room name','Nome da sala'],password:['Password (optional)','Senha (opcional)'],createRoom:['Create room','Criar sala'],joinRoom:['Join','Entrar'],refresh:['Refresh','Atualizar'],ready:['Ready','Pronto'],hostStart:['Start battle','Iniciar batalha'],leave:['Leave room','Sair da sala'],kick:['Kick player','Expulsar jogador'],kickConfirm:['Kick the other player from this room?','Expulsar o outro jogador desta sala?'],rooms:['Rooms','Salas'],noRooms:['No rooms available','Nenhuma sala disponível'],server:['Server','Servidor'],serverHint:['The Championship Worker must be deployed before public matchmaking works.','O Worker Championship precisa estar publicado para as salas públicas funcionarem.'],serverRosterOutdated:['The Online server is out of date and does not recognize this Digimon yet. Try again after the server is updated.','O servidor Online está desatualizado e ainda não reconhece este Digimon. Tente novamente depois que o servidor for atualizado.'],badFighter:['Invalid fighter data','Dados de lutador inválidos'],battleNotFinished:['Battle is still running','A batalha ainda está ocorrendo'],slowDown:['Please wait before trying again','Aguarde antes de tentar novamente'],battleCancelled:['Battle cancelled; no result recorded.','Batalha cancelada; nenhum resultado registrado.'],timeout:['Time limit · highest remaining HP percentage wins','Limite de tempo · vence a maior porcentagem de HP restante'],disobey:['Hesitating','Hesitando'],hit:['Hit','Golpe'],special:['Special','Especial'],miss:['Miss','Errou'],heal:['Heal','Cura'],defend:['Defend','Defesa'],evade:['Evade','Esquiva'],music:['Music volume','Volume da música'],sfxVolume:['Sound effects','Efeitos sonoros'],aboutText:['A personal, noncommercial fan project by Armster, inspired by virtual pets and Digimon World Championship. Armster owns an original 20th anniversary V-Pet. Digimon characters belong to their respective owners. This experimental fork is unofficial and unaffiliated.','Um projeto pessoal e não comercial de Armster, inspirado em bichinhos virtuais e Digimon World Championship. Armster possui um V-Pet original de 20 anos. Os personagens Digimon pertencem aos seus respectivos donos. Este fork experimental não é oficial nem afiliado.'],helpHabitat:['Drag either pet to a cage to train automatically every 15 seconds. Drag empty ground to move the camera, or use the zone buttons. Meat and Medicine can be dragged from the toolbar. A tap selects a tool; tap the ground or pet to use it.','Arraste qualquer pet a uma área para treinar automaticamente a cada 15 segundos. Arraste o chão para mover a câmera ou use os botões de área. Arraste Carne e Remédio da barra. Um toque seleciona a ferramenta; toque no chão ou pet para usá-la.'],helpCare:['Meat is unlimited. Hungry pets reserve a piece, walk to it and eat it in three bites. Fatigue stops training at 95; Rest recovers 95 per minute. Hunger continues to fall. Use Medicine for sickness or injury and Clean on waste. Ignored severe needs add a care mistake every 2 minutes. Pets never die automatically.','Carne é ilimitada. Pets com fome reservam um pedaço, caminham até ele e comem em três mordidas. Fadiga interrompe o treino em 95; Descanso recupera 95 por minuto. A alimentação continua caindo. Use Remédio para doença ou ferimento e Limpar na sujeira. Necessidades graves ignoradas geram um erro a cada 2 minutos. Pets nunca morrem automaticamente.'],helpEvo:['Each pet has its own clock: Egg 1 min, Baby I 5 min, Baby II 12 min, Rookie 25 min, Champion 40 min, Ultimate 60 min. Requirements are checked continuously. Training shapes the branch. Eligible routes are ranked by relevant training points, then route priority, then species ID. Missing a requirement never permanently blocks evolution.','Cada pet tem seu relógio: Ovo 1 min, Baby I 5 min, Baby II 12 min, Rookie 25 min, Champion 40 min, Ultimate 60 min. Requisitos são verificados continuamente. Treino define a ramificação. Rotas elegíveis são ordenadas por pontos relevantes de treino, prioridade da rota e ID da espécie. Não cumprir um requisito nunca bloqueia a evolução permanentemente.'],helpBattle:['Choose a Rookie or older pet. Combat is automatic: HP is health, TP fuels specials, Attack powers melee, Defense mitigates damage, Wisdom powers specials and influences choices, Speed controls movement and attack recovery. Innate behavior varies by species. A brief hesitation has a cooldown. Online: both players ready, host starts, both must accept a rematch.','Escolha um pet Rookie ou superior. Combate automático: HP é vida, TP alimenta especiais, Ataque fortalece corpo a corpo, Defesa reduz dano, Sabedoria fortalece especiais e influencia escolhas, Velocidade controla movimento e recuperação dos ataques. Comportamento varia por espécie. A hesitação breve tem intervalo de proteção. Online: ambos prontos, host inicia e ambos aceitam revanche.'],helpSave:['NEW GAME starts a separate Championship save. Browser autosave runs every 30 seconds. SAVE & EXIT downloads a portable .dbcsave file. LOAD SAVE imports it. The original Ver.20th save is never overwritten. Deleting a pet frees one slot and preserves your collection.','NOVO JOGO inicia um save próprio de Championship. Autosave no navegador a cada 30 segundos. SALVAR E SAIR baixa um arquivo .dbcsave portátil. CARREGAR SAVE importa esse arquivo. O save original Ver.20th nunca é sobrescrito. Deletar um pet libera um slot e preserva a coleção.']
});

Object.assign(DMI18N.S,{"colosseum": ["Colosseum", "Coliseu"], "noMedicine": ["{name} does not need medicine.", "{name} não precisa de remédio."], "tips": ["TIPS?", "DICAS?"], "tipStat": ["Perhaps a little more {stat} would help {name}?", "Talvez um pouco mais de {stat} seja útil para {name}?"], "tipWins": ["Perhaps {name} needs a few more victories?", "Talvez {name} precise de mais algumas vitórias?"], "tipBattles": ["Perhaps {name} needs more battle experience?", "Talvez {name} precise de mais experiência em batalhas?"], "tipCare": ["Perhaps {name} needs a different care routine?", "Talvez {name} precise de uma rotina de cuidados diferente?"], "helpTips": ["TIPS lights up only when a pet is still missing evolution requirements two minutes after its minimum stage age. Each stuck pet gets a separate subtle hint for its closest route; species are never revealed. The button turns off when nobody is stuck.", "DICAS acende somente quando faltam requisitos de evolução dois minutos após a idade mínima da fase. Cada pet empacado recebe uma dica separada da linha mais próxima, sem revelar a espécie. O botão apaga quando ninguém está empacado."], "resetColosseum": ["Reset Colosseum", "Reiniciar Coliseu"], "resetColosseum1": ["Restart at round 1? All unlocked rewards, collection and records are kept.", "Voltar à rodada 1? Todas as recompensas desbloqueadas, coleção e recordes permanecem."], "resetColosseum2": ["Confirm resetting battle progress only? Unlocks will not be removed or duplicated.", "Confirmar reinício somente do progresso das batalhas? Desbloqueios não serão removidos nem duplicados."], "helpReset": ["RESET COLOSSEUM requires two confirmations and returns to round 1. Unlocks, collection, best round and clear records remain permanent; replaying does not duplicate unlock rewards.", "REINICIAR COLISEU exige duas confirmações e volta à rodada 1. Desbloqueios, coleção, melhor rodada e conclusões permanecem; rejogar não duplica recompensas de desbloqueio."], "specializationHelp": ["Each stage has a shared training budget and a per-stat cap (shown beside each value). At the stat cap, training gives nothing. At a full budget, training redistributes existing points into your chosen stat at half speed; it never automatically raises other stats. You can change specialization without a permanent evolution lock.", "Cada fase tem orçamento compartilhado e teto por atributo (mostrado ao lado do valor). No teto do atributo, o treino não dá pontos. Com orçamento cheio, o treino redistribui pontos existentes para o atributo escolhido à metade da velocidade; nunca aumenta outros atributos automaticamente. É possível mudar de especialização sem bloquear a evolução definitivamente."], "helpCare": ["Pets only eat food in their own cage and cannot leave it by themselves. Meat is eaten in three bites, and at most six pieces can be active in the nursery at once. Clean removes waste and leftover meat. Medicine only treats sickness or injury, marked with a medical cross and exclamation above the pet. Each successful training costs 2.5 fatigue, plus 9 per minute outside Rest; training stops at 95. Rest recovers 95 per minute. Ignored severe needs add one care mistake every two minutes. Pets never die automatically.", "Pets só comem na própria cage e não saem sozinhos. Carne é comida em três mordidas, e no máximo seis pedaços podem ficar ativos no viveiro ao mesmo tempo. Limpar remove sujeira e carne abandonada. Remédio só trata doença ou ferimento, sinalizado por cruz médica e exclamação acima do pet. Cada treino bem-sucedido custa 2,5 de fadiga, além de 9 por minuto fora de Descanso; treino para em 95. Descanso recupera 95 por minuto. Necessidades graves ignoradas geram um erro a cada dois minutos. Pets nunca morrem automaticamente."]});
